g=defaultdict(list)
for r in rows:g[r['set_id']].append(r)
tot=hits=0
for rs in g.values():
 deep=[r for r in rs if r['depth']>=4 and r['residual'] and r['activation'] in ('silu','gelu') and r['n_ln']>=2]
 shallow=[r for r in rs if r['depth']<=2 and r['residual'] and r['activation']=='leaky_relu' and r['n_ln']>=1]
 for a in deep:
  for b in shallow:
   if a['optimizer']['type']==b['optimizer']['type'] and abs(a['optimizer']['lr']-b['optimizer']['lr'])<1e-12:
    tot+=1;hits+=a['mean']<b['mean']
print(tot,hits)
